using System;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class EmployerDashboardPage:UserControl{public EmployerDashboardPage(){BackColor=Theme.Background;var cards=new FlowLayoutPanel{Dock=DockStyle.Top,Height=145};cards.Controls.Add(Kpi(L.Fa?"فرصت‌های باز":"Open jobs","SELECT COUNT(*) FROM Jobs WHERE Status='Open'"));cards.Controls.Add(Kpi(L.Fa?"کل درخواست‌ها":"Applications","SELECT COUNT(*) FROM Applications"));cards.Controls.Add(Kpi(L.Fa?"در مرحله مصاحبه":"In interview","SELECT COUNT(*) FROM Applications WHERE Stage='Interview'"));cards.Controls.Add(Kpi(L.Fa?"پیشنهادهای منتظر تایید":"Offers awaiting approval","SELECT COUNT(*) FROM Offers WHERE Status='PendingApproval'"));Controls.Add(cards);var tabs=new TabControl{Dock=DockStyle.Fill};tabs.TabPages.Add(Tab(L.Fa?"قیف استخدام":"Hiring funnel","SELECT Stage,COUNT(*) AS Total FROM Applications GROUP BY Stage ORDER BY Total DESC"));tabs.TabPages.Add(Tab(L.Fa?"عملکرد فرصت‌ها":"Job performance","SELECT TOP 30 j.Title,j.City,j.Status,COUNT(a.Id) AS Applications,ISNULL(AVG(CAST(a.Score AS FLOAT)),0) AS AvgScore FROM Jobs j LEFT JOIN Applications a ON a.JobId=j.Id GROUP BY j.Title,j.City,j.Status ORDER BY Applications DESC"));tabs.TabPages.Add(Tab(L.Fa?"پیشنهادها":"Offers","SELECT TOP 30 o.Id,c.FullName,j.Title,o.Salary,o.Status,o.ExpiryDate FROM Offers o JOIN Applications a ON a.Id=o.ApplicationId JOIN Candidates c ON c.Id=a.CandidateId JOIN Jobs j ON j.Id=a.JobId ORDER BY o.CreatedAt DESC"));Controls.Add(tabs);tabs.BringToFront();}Panel Kpi(string t,string sql){var p=Ui.Card();p.Size=new Size(245,115);var a=Ui.Label(t,10,true);a.Location=new Point(16,16);var n=Ui.Label(Convert.ToString(Database.Scalar(sql)),24,true);n.ForeColor=Theme.Primary;n.Location=new Point(16,53);p.Controls.Add(a);p.Controls.Add(n);return p;}TabPage Tab(string t,string sql){var p=new TabPage(t);var g=Ui.Grid();g.DataSource=Database.Query(sql);p.Controls.Add(g);return p;}}}